import React from 'react';
import { Link, useLocation } from 'react-router-dom';

const Navigation: React.FC = () => {
  const location = useLocation();

  const navItems = [
    { name: 'Home', path: '/dashboard' },
    { name: 'Staff', path: '/staff' },
    { name: 'Missions', path: '/missions' },
    { name: 'Market', path: '/market' },
  ];

  return (
    <nav className="fixed bottom-0 left-0 right-0 bg-hitman-gray border-t border-gray-700 md:relative md:border-t-0 md:bg-transparent z-50">
      <ul className="flex justify-around md:flex-col md:gap-2 p-2">
        {navItems.map((item) => (
          <li key={item.path}>
            <Link
              to={item.path}
              className={`flex flex-col items-center md:items-start md:px-4 md:py-2 rounded transition-colors ${
                location.pathname === item.path
                  ? 'text-hitman-red md:bg-hitman-gray md:text-white'
                  : 'text-gray-400 hover:text-white'
              }`}
            >
              <span className="text-[10px] md:text-sm font-bold uppercase tracking-widest">{item.name}</span>
            </Link>
          </li>
        ))}
      </ul>
    </nav>
  );
};

export default Navigation;
